import AVFoundation
import SpriteKit
import UIKit

/// Sound effects (generated by tools/make_sounds.py) and haptics for game events (issue #20).
final class Feedback {
    enum Sound: String, CaseIterable {
        case shoot, attach, clank, boost, gem, checkpoint, crash, finish
    }

    enum Haptic {
        case light, medium, heavy, rigid, success
    }

    /// A few players per sound so rapid repeats can overlap.
    private var players: [Sound: [AVAudioPlayer]] = [:]
    /// Sounds whose files weren't found in the app bundle (usually: `xcodegen` wasn't re-run).
    private(set) var missingSounds: [String] = []
    private let light = UIImpactFeedbackGenerator(style: .light)
    private let medium = UIImpactFeedbackGenerator(style: .medium)
    private let heavy = UIImpactFeedbackGenerator(style: .heavy)
    private let rigid = UIImpactFeedbackGenerator(style: .rigid)
    private let notification = UINotificationFeedbackGenerator()

    init() {
        // Ambient: respects the silent switch (the developer keeps the phone on silent) and mixes
        // with the player's own music.
        let session = AVAudioSession.sharedInstance()
        do {
            try session.setCategory(.ambient, options: [.mixWithOthers])
            try session.setActive(true)
        } catch {
            print("Feedback: audio session setup failed: \(error)")
        }
        for sound in Sound.allCases {
            guard let url = Bundle.main.url(forResource: sound.rawValue, withExtension: "wav") else {
                missingSounds.append("\(sound.rawValue).wav")
                continue
            }
            let pool = (0..<3).compactMap { _ in try? AVAudioPlayer(contentsOf: url) }
            pool.forEach { $0.prepareToPlay() }
            players[sound] = pool
        }
        if !missingSounds.isEmpty {
            print("Feedback: missing from the app bundle: \(missingSounds.joined(separator: ", "))")
        }
        prepare()
    }

    @discardableResult
    func play(_ sound: Sound) -> Bool {
        guard let pool = players[sound], let player = pool.first(where: { !$0.isPlaying }) ?? pool.first else { return false }
        player.currentTime = 0
        return player.play()
    }

    /// Plays a sound and describes the audio setup, for the Tune panel's sound check.
    func soundCheck() -> String {
        let played = play(.finish)
        let session = AVAudioSession.sharedInstance()
        let outputs = session.currentRoute.outputs.map(\.portName).joined(separator: ", ")
        let loaded = players.count
        var lines = [
            "Played: \(played ? "yes" : "NO")",
            "Sounds loaded: \(loaded)/\(Sound.allCases.count)",
            "Volume: \(Int(session.outputVolume * 100))%",
            "Output: \(outputs.isEmpty ? "none" : outputs)",
            "Session: \(session.category.rawValue.replacingOccurrences(of: "AVAudioSessionCategory", with: ""))",
        ]
        if !missingSounds.isEmpty { lines.append("Missing: \(missingSounds.joined(separator: ", "))") }
        return lines.joined(separator: "\n")
    }

    func haptic(_ haptic: Haptic) {
        switch haptic {
        case .light: light.impactOccurred()
        case .medium: medium.impactOccurred()
        case .heavy: heavy.impactOccurred()
        case .rigid: rigid.impactOccurred()
        case .success: notification.notificationOccurred(.success)
        }
        prepare()
    }

    private func prepare() {
        light.prepare()
        medium.prepare()
        heavy.prepare()
        rigid.prepare()
        notification.prepare()
    }
}
